const $=s=>document.querySelector(s);const uiDefaults=()=>({research:'overview',training:'news',life:'room',paperSearch:'',paperTopic:'',paperYear:'',paperStatus:'',paperType:'',fileSearch:'',fileCategory:'',fileSort:'added',article:'n1',newsCategory:'',translationMode:'PT-ZH',translationReveal:'',vocabSaved:false,focusRange:'today',diarySearch:'',diaryDate:'',diaryTag:'',financeMonth:dateKey().slice(0,7)});export const ui=uiDefaults();let route='home',toastTimer,cityResults=[],objectUrls=[],busy=false,pendingBackup=null,dirtyForm=null,pendingProfileSwitch='';let persistedDay=dateKey();
function resetUi(){for(const key of Object.keys(ui))delete ui[key];Object.assign(ui,uiDefaults());cityResults=[];pendingBackup=null}
function performProfileSwitch(id){switchProfile(id);pendingProfileSwitch='';dirtyForm=null;resetUi();close();render();toast(`CURRENT PROFILE · ${currentProfile().displayName}`)}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
window.addEventListener('storage-failed',()=>toast('本地存储已满或不可用：本次修改未持久保存，请导出备份。'));
function effects(){document.body.className=state.effects?'effects-on':'effects-off'}
function modal(title,body){$('#modal').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="dialog-close" data-action="close" aria-label="关闭对话框">×</button></div><div class="dialog-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function close(){ if($('#modal').open)$('#modal').close();objectUrls.forEach(URL.revokeObjectURL);objectUrls=[] }
$('#modal').addEventListener('close',()=>{objectUrls.forEach(URL.revokeObjectURL);objectUrls=[]});
function saved(message='已保存到当前浏览器'){if(save())toast(message);render()}
function getRoute(){const value=location.hash.slice(1);if(value==='vault'){ui.research='library';history.replaceState(null,'','#research');return'research'}return value==='comms'?'mission':value==='study'?'training':destinations.some(d=>d[0]===value)?value:'home'}
function navigate(value){if(route===value){render();return}location.hash=value}
function render(){if(!hasProfile()){$('#os').innerHTML=welcome();document.body.className='effects-off';return}route=getRoute();effects();const item=destinations.find(d=>d[0]===route);let body='';if(route==='home')body=cityScreen();if(route==='research')body=research(ui);if(route==='training')body=training(ui);if(route==='focus')body=focus(ui);if(route==='life')body=ui.life==='room'?roomScreen(ui):life(ui);if(route==='mission')body=mission(ui);if(route==='mission'||route==='focus'){$('#os').innerHTML=missionShell(route,body);clock();return}const scene=route==='home'||route==='life'&&ui.life==='room';$('#os').innerHTML=shell(route,`<main id="main" tabindex="-1" class="${scene?'scene-main':'terminal-main'}">${scene?body:`<div class="page"><div class="page-header"><h1>${item[1]}</h1><a href="#home">RETURN TO CITY</a></div>${body}</div>`}</main>`);clock();bindFiles();if(route==='training')refreshNews()}

async function refreshNews(force=false){const pending=loadNews(force);if(force)toast('正在读取官方免费 RSS…');if(await pending){if(route==='training')render()}}
async function copyTraining(id){const record=id?historyRecords().find(r=>r.id===id):currentRecord(ui.translationMode);if(!record?.originalExcerpt){toast('请先选择原文');return}const text=chatPrompt(record);try{await navigator.clipboard.writeText(text);toast('已复制；请在 ChatGPT 中手动粘贴')}catch{modal('COPY FOR CHATGPT',`<p>若未自动复制，请选中下方内容后复制。</p><textarea id="copy-fallback" readonly style="width:100%;min-height:320px">${esc(text)}</textarea>`);const field=$('#copy-fallback');field.focus();field.select();if(document.execCommand('copy'))toast('已复制')}}
function clock(){if($('#os-clock'))$('#os-clock').textContent=new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});if($('#os-date'))$('#os-date').textContent=dateKey().replaceAll('-','.')+' '+['SUN','MON','TUE','WED','THU','FRI','SAT'][new Date().getDay()]}
function taskCompletion(id,done){const reward=completeTask(state,id,done);save();if(reward.after>reward.before)toast(`LEVEL UP · LV.${reward.before} → LV.${reward.after}`);else if(reward.amount)toast(`QUEST COMPLETE · +${reward.amount} EXP`);else toast(done?'QUEST COMPLETE · 此任务不重复发放 EXP':'任务已恢复，重新完成不会重复奖励');render()}
function moveMonth(key,amount){const [y,m]=(ui[key]||dateKey().slice(0,7)).split('-').map(Number);ui[key]=dateKey(new Date(y,m-1+amount,1)).slice(0,7);render()}
async function loadWeather(city){if(busy)return;busy=true;toast('正在获取天气…');try{const w=await weather(city);state.city=city;state.weather=w;save();close();render();toast('天气已更新')}catch(e){toast('天气获取失败：'+e.message)}finally{busy=false}}
async function doImport(files){if(busy)return;busy=true;const indicator=$('#import-status');if(indicator)indicator.textContent='正在本地读取，请稍候…';try{const result=await importFiles(files);render();toast(`已导入 ${result.added} 个文件，跳过 ${result.skipped} 个重复、过大或不支持的文件。`)}catch(e){toast('导入失败：'+e.message)}finally{busy=false}}
function bindFiles(){const picker=$('#file-picker');if(picker)picker.addEventListener('change',()=>doImport(picker.files));const backup=$('#backup-picker');if(backup)backup.addEventListener('change',()=>readBackup(backup.files?.[0]).catch(error=>toast('备份读取失败：'+error.message)));const drop=$('#dropzone');if(drop){drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');doImport(e.dataTransfer.files)})}}
async function readBackup(file){if(!file)return;if(file.size>25*1024*1024)throw Error('备份文件过大');pendingBackup=parseBackup(await file.text());modal('IMPORT BACKUP',importOptions(file.name))}
async function openFile(id){const metadata=state.files.find(f=>f.id===id),file=await getFile(id);if(!file){toast('本地文件不可用，请重新导入。');return}metadata.lastOpened=Date.now();save();if(metadata.type==='TXT'){modal('LOCAL TEXT / '+esc(metadata.name),`<div class="pre">${esc(await file.text())}</div>`)}else if(metadata.type==='PDF'){const url=URL.createObjectURL(new Blob([file],{type:'application/pdf'}));objectUrls.push(url);modal('LOCAL PDF',`<p>${esc(metadata.name)}</p><iframe title="PDF 文献预览" src="${url}" style="width:100%;height:58vh;border:1px solid var(--border)"></iframe><a class="button" href="${url}" download="${esc(metadata.name)}">下载本地文件</a>`)}else{download(file,metadata.name);toast('文件已提供下载，可用本地阅读器打开。')}render()}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
