let pendingDelete;function confirmDelete(label,callback,confirmLabel='确认删除',cancelLabel='取消'){pendingDelete=callback;modal('CONFIRM DELETE',`<p>确定删除${label}？</p><p class="muted small">此操作无法撤销。</p><div class="actions">${button(cancelLabel,'close')}${button(confirmLabel,'confirm-delete','','danger')}</div>`)}clickActions['confirm-delete']=async()=>{const fn=pendingDelete;pendingDelete=null;if(fn)await fn()};
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const fn=clickActions[el.dataset.action];if(fn){try{if(el.dataset.action==='article')ui.article=el.dataset.id;await fn(el)}catch(error){toast('操作未完成：'+error.message);console.error(error)}}});
document.addEventListener('change',e=>{const el=e.target,action=el.dataset.change;if(!action)return;switch(action){case 'task':taskCompletion(el.dataset.id,el.checked);return;case 'chapter':{const chapter=state.chapters.find(record=>String(record.id)===String(el.dataset.id));if(chapter){chapter.progress=Number(el.value);chapter.status=chapter.progress>=100?'COMPLETE':chapter.progress>0&&chapter.status==='NOT STARTED'?'IN PROGRESS':chapter.status;chapter.updatedAt=new Date().toISOString()}break}case 'file-category':state.files.find(f=>f.id===el.dataset.id).category=el.value;break;case 'file-tags':state.files.find(f=>f.id===el.dataset.id).tags=el.value;break;case 'translation-source':ui.article=el.value;break;case 'finance-month':if(el.value)ui.financeMonth=el.value;break}save();render()});
document.addEventListener('input',e=>{const form=e.target.closest('form[data-form]');if(form&&!['paper-search','translation-search','diary-search','file-search','city','profile-create','profile-delete','profiles-delete-all','backup-replace'].includes(form.dataset.form))dirtyForm=form;const focusForm=e.target.closest('[data-form="focus-log"]');if(focusForm&&!focusForm.dataset.id){state.focusDraft=Object.fromEntries(new FormData(focusForm));save()}if(e.target.name==='energy'&&$('#energy-value')){$('#energy-value').textContent=e.target.value;e.target.style.setProperty('--energy',Number(e.target.value)*10+'%')}const key=e.target.dataset.draft;if(key){state.drafts[key]=e.target.value;save()}});
const submitActions={
 'profile-create':d=>{createProfile(d.displayName);resetUi();close();render();toast(`LOCAL PROFILE CREATED · ${currentProfile().displayName}`)},
 'profile-delete':async d=>{if(d.confirm!=='DELETE')throw Error('请输入 DELETE');const id=currentProfile().profileId,ids=state.files.map(f=>f.id);await purgeProfileFiles(id,ids);deleteCurrentProfile();resetUi();close();render();toast('当前本地档案已删除')},
 'profiles-delete-all':async d=>{if(d.confirm!=='DELETE ALL')throw Error('请输入 DELETE ALL');await purgeAllAppFiles();deleteAllProfiles();resetUi();close();render();toast('double’s home 的本地档案已清理')},
 'backup-replace':d=>{if(d.confirm!=='REPLACE'||!pendingBackup)throw Error('请输入 REPLACE');importBackup(pendingBackup,'replace');pendingBackup=null;resetUi();close();render();toast('CURRENT PROFILE REPLACED')},
 'task':(d)=>{saveQuest(state,{title:d.text,category:({'论文':'RESEARCH','葡语':'PORTUGUESE','翻译':'TRANSLATION','生活':'LIFE'})[d.cat]||'OTHER',questType:'DAILY',status:'TODAY',dueDate:dateKey()});saved('任务已添加');close()},'thesis':d=>{state.thesisTitle=d.title;state.deadline=d.deadline;saved('论文设置已保存')},
 'chapter':(d,f)=>{saveChapter(state,d,f.dataset.id);saved('CHAPTER SAVED');close()},'theory':(d,f)=>{saveTheory(state,d,f.dataset.id);saved('THEORY SAVED');close()},
 'paper':(d,f)=>{saveLiterature(state,d,f.dataset.id);saved('LITERATURE SAVED');close()},'paper-search':d=>{ui.paperSearch=d.q;ui.paperTopic=d.topic;ui.paperYear=d.year;ui.paperStatus=d.status;ui.paperType=d.type;render()},
 'review-theme':(d,f)=>{d.literatureIds=new FormData(f).getAll('literatureIds');saveReviewTheme(state,d,f.dataset.id);saved('REVIEW THEME SAVED');close()},
 'training-goal':d=>{setTrainingGoal(state,d);saved('学习目标已保存');close()},'vocab':d=>{state.vocab.push({...d,id:uid(),saved:true,reviews:0});saved('表达已加入个人词库');close()},'translation-search':d=>{ui.translationFilters=d;render()},'translation':(d,f)=>{state.translations.push(makeRecord(f.dataset.mode,d.text));if(!state.trainingDays.includes(dateKey()))state.trainingDays.push(dateKey());saved('原文与译文已保存到本机历史')},
 'quest':(d,f)=>{const t=saveQuest(state,d,f.dataset.id);if(t.questType==='MAIN'&&!state.mainQuestId)state.mainQuestId=t.id;saved('QUEST SAVED');close()},'focus-log':(d,f)=>{saveFocus(state,d,f.dataset.id);if(!f.dataset.id)state.focusDraft={category:d.category,durationMinutes:'',note:'',linkedTaskId:'',date:dateKey()};saved('SESSION LOGGED');close()},'mood':d=>{state.moods[dateKey()]={...d,energy:Number(d.energy)};saved('今日心情已记录')},'diary':(d,f)=>{const diary={...d,id:f.dataset.id||uid()};const i=state.diaries.findIndex(x=>x.id===diary.id);if(i>=0)state.diaries[i]=diary;else state.diaries.push(diary);saved('日记已保存');close()},'diary-search':d=>{ui.diarySearch=d.q;ui.diaryDate=d.date;ui.diaryTag=d.tag;render()},'finance':(d,f)=>{const record={...d,id:f.dataset.id||uid(),amount:Math.round(Number(d.amount)*100)/100};const i=state.finance.findIndex(x=>x.id===record.id);if(i<0)state.finance.push(record);else state.finance[i]=record;saved('账目已保存');close()},'file-search':d=>{ui.fileSearch=d.q;ui.fileCategory=d.category;ui.fileSort=d.sort;render()},
 'city':async d=>{const target=$('#city-results');target.textContent='正在搜索城市…';try{cityResults=await findCities(d.name);if(!target.isConnected)return;target.innerHTML=cityResults.map((c,i)=>`<div class="listrow"><div class="content"><h3>${esc(c.name)}</h3><p>${esc(c.admin1||'')} · ${esc(c.country||'')}</p></div>${button('选择','city-select',`data-id="${i}"`)}</div>`).join('')||'<p>没有找到城市，请尝试英文名称或“城市, 国家”。</p>'}catch(error){if(target.isConnected)target.innerHTML=`<div class="notice error">${esc(error.message)}。请重试。</div>`}}
 ,'ui-text':d=>{state.uiText={sidebarMotto:String(d.sidebarMotto||DEFAULT_UI_TEXT.sidebarMotto).trim().slice(0,120)||DEFAULT_UI_TEXT.sidebarMotto,footerQuote:String(d.footerQuote||DEFAULT_UI_TEXT.footerQuote).trim().slice(0,180)||DEFAULT_UI_TEXT.footerQuote};saved('PERSONAL UI TEXT SAVED');close()}
};
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form));if(Object.values(data).some(v=>typeof v==='string'&&v.length>100000)){toast('单个字段过长，请拆分记录');return}try{await submitActions[form.dataset.form]?.(data,form);dirtyForm=null;if(pendingProfileSwitch)performProfileSwitch(pendingProfileSwitch)}catch(error){toast(error.message);console.error(error)}});
window.addEventListener('hashchange',()=>{if(getRoute()==='life'&&route!=='life')ui.life='room';close();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});document.addEventListener('visibilitychange',()=>{if(!document.hidden){clock()}});
window.addEventListener('storage',e=>{if(e.key?.startsWith('double-home:'))toast('另一个窗口更新了本地档案，请刷新后继续编辑，避免覆盖。')});
render();setInterval(()=>{if(dateKey()!==persistedDay){persistedDay=dateKey();render()}clock()},1000);

setInterval(()=>{if(route==='training'&&!document.hidden)refreshNews()},60000);
